// HistoricalVisitForm: صفحة «الزيارات القديمة» — إضافة/تعديل زيارة تمت بالفعل
// إلى سجل الزيارات: اسم، وصف، صورة، عدد الطلاب (رقم فقط)، مشرفين، تاريخ ماضٍ،
// والوقت اختياري. لا يُفتح لها تسجيل ولا يظهر لها عدّاد.
function HistoricalVisitForm({initial,submitLabel,onSubmit,onCancel,supervisors=[]}){
  const [form,setForm]=useState({title:'',description:'',date:'',time:'',studentsCount:'',location:'',imageUrl:'',colonelId:'',majorId:'',doctorIds:[],studentIds:[],...initial,...supervisorIdsFromVisit(initial)});
  const [image,setImage]=useState();
  const [removeImage,setRemoveImage]=useState(false);
  const [err,setErr]=useState('');
  const [loading,setLoading]=useState(false);
  const filePreview=image?URL.createObjectURL(image):'';
  const urlPreview=form.imageUrl&&/^https?:\/\//i.test(form.imageUrl)?form.imageUrl.trim():'';
  const existing=initial&&initial.image&&initial.image!=='/images/visit-placeholder.svg'?initial.image:'';
  const hasImage=!removeImage&&Boolean(filePreview||urlPreview||existing);
  const previewSrc=hasImage?(filePreview||urlPreview||existing):'/images/visit-placeholder.svg';
  useEffect(()=>{if(filePreview)return()=>URL.revokeObjectURL(filePreview)},[filePreview]);
  const submit=async e=>{
    e.preventDefault();
    if(!form.title.trim())return setErr('برجاء إدخال اسم الزيارة');
    if(!form.date)return setErr('برجاء تحديد تاريخ الزيارة');
    if(form.date>todayStr())return setErr('الزيارة القديمة يجب أن يكون تاريخها في الماضي');
    if(form.studentsCount!==''&&form.studentsCount!=null&&!/^\d+$/.test(String(form.studentsCount).trim()))return setErr('عدد الطلاب يجب أن يكون رقماً صحيحاً فقط');
    setLoading(true);setErr('');
    const fd=new FormData();
    const {colonelId,majorId,doctorIds,studentIds,supervisors:_s,registered,hasWhatsappGroup,id,status,createdAt,publishedAt,publishAt,deletedAt,historical,image:_img,...rest}=form;
    const payload={...rest,studentsCount:form.studentsCount===''?null:Number(form.studentsCount),imageUrl:form.imageUrl||'',removeImage:removeImage||undefined,supervisorIds:buildSupervisorIds(form)};
    fd.append('data',JSON.stringify(payload));
    if(image)fd.append('image',image);
    try{await onSubmit(fd)}catch(e){setErr(e.message)}finally{setLoading(false)}
  };
  return <form onSubmit={submit}>{err&&<div className="error">{err}</div>}<div className="form-grid"><Field label="اسم الزيارة" value={form.title} onChange={v=>setForm({...form,title:v})} required/><Field label="تاريخ الزيارة (بالماضي)" type="date" max={todayStr()} value={form.date} onChange={v=>setForm({...form,date:v})} required/><Field label="وقت الزيارة (اختياري)" type="time" value={form.time} onChange={v=>setForm({...form,time:v})}/><Field label="عدد الطلاب (رقم فقط — اختياري)" type="number" min="0" step="1" inputMode="numeric" value={form.studentsCount??''} onChange={v=>setForm({...form,studentsCount:v})} placeholder="مثال: 45"/><Field label="المكان (اختياري)" value={form.location} onChange={v=>setForm({...form,location:v})}/><Field label="وصف الزيارة" value={form.description} onChange={v=>setForm({...form,description:v})}/></div><SupervisorPicker supervisors={supervisors} form={form} setForm={setForm}/><Field label="رابط صورة الزيارة (اختياري — بدل الرفع)" value={form.imageUrl} onChange={v=>{setForm({...form,imageUrl:v});setRemoveImage(false)}} placeholder="https://example.com/photo.jpg"/><label className="upload"><CalendarDays/><span><b>صورة الزيارة (ملف)</b><small>{image?image.name:'اختياري — له الأولوية على الرابط'}</small></span><input type="file" accept="image/*" onChange={e=>{setImage(e.target.files[0]);setRemoveImage(false)}}/></label><div className="visit-preview"><small>معاينة الصورة</small><img src={imgSrc(previewSrc)} onError={e=>{const t=e.currentTarget;if(t.dataset.fallback)return;t.dataset.fallback='1';t.src='/images/visit-placeholder.svg'}}/>{hasImage&&<button type="button" className="link-danger remove-img" onClick={()=>{setImage();setForm({...form,imageUrl:''});setRemoveImage(true)}}><Trash2 size={14}/> إزالة الصورة</button>}</div><div className="form-actions">{onCancel&&<button type="button" className="btn btn-muted" onClick={onCancel}>إلغاء</button>}<button className="btn" disabled={loading}>{loading?'جارٍ الحفظ...':submitLabel} <Plus/></button></div></form>;
}
